66">string</a></span> <span class="parameter" style="color:#3A95FF">\$tok</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-parser.trace.php" class="methodname" style="color:#CC7832">trace</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/parle-parser.validate.php" class="methodname" style="color:#CC7832">validate</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.parle-lexer.php" class="type Parle\Lexer" style="color:#EAB766">Parle\Lexer</a></span> <span class="parameter" style="color:#3A95FF">\$lexer</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>   }</div>  </div>  <div class="section" id="parle-parser.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="parle-parser.constants.action-error"><strong><span>{@link Parle\Parser::ACTION_ERROR}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-parser.constants.action-shift"><strong><span>{@link Parle\Parser::ACTION_SHIFT}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-parser.constants.action-reduce"><strong><span>{@link Parle\Parser::ACTION_REDUCE}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-parser.constants.action-goto"><strong><span>{@link Parle\Parser::ACTION_GOTO}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-parser.constants.action-accept"><strong><span>{@link Parle\Parser::ACTION_ACCEPT}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-parser.constants.error-syntax"><strong><span>{@link Parle\Parser::ERROR_SYNTAX}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-parser.constants.error-non-associative"><strong><span>{@link Parle\Parser::ERROR_NON_ASSOCIATIVE}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>             <dt id="parle-parser.constants.error-unknown-token"><strong><span>{@link Parle\Parser::ERROR_UNKNOWN_TOKEN}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>       </dl>  </div>  <div class="section" id="parle-parser.props">   <h2 class="title">属性</h2>   <dl>         <dt id="parle-parser.props.action"><var class="varname">action</var></dt>     <dd>      <p class="para">Current parser action that matches one of the action class constants, readonly.</p>     </dd>             <dt id="parle-parser.props.reduceId"><var class="varname">reduceId</var></dt>     <dd>      <p class="para">Grammar rule id just processed in the reduce action. The value corresponds either to a token or to a production id. Readonly.</p>     </dd>       </dl>  </div> </div>  <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Parle\Parser::advance} — Process next parser rule</li><li>{@link Parle\Parser::build} — Finalize the grammar rules</li><li>{@link Parle\Parser::consume} — Consume the data for processing</li><li>{@link Parle\Parser::dump} — Dump the grammar</li><li>{@link Parle\Parser::errorInfo} — Retrieve the error information</li><li>{@link Parle\Parser::left} — Declare a token with left-associativity</li><li>{@link Parle\Parser::nonassoc} — Declare a token with no associativity</li><li>{@link Parle\Parser::precedence} — Declare a precedence rule</li><li>{@link Parle\Parser::push} — Add a grammar rule</li><li>{@link Parle\Parser::reset} — Reset parser state</li><li>{@link Parle\Parser::right} — Declare a token with right-associativity</li><li>{@link Parle\Parser::sigil} — Retrieve a matching part of a rule</li><li>{@link Parle\Parser::sigilCount} — Number of elements in matched rule</li><li>{@link Parle\Parser::sigilName} — Retrieve a rule or token name</li><li>{@link Parle\Parser::token} — Declare a token</li><li>{@link Parle\Parser::tokenId} — Get token id</li><li>{@link Parle\Parser::trace} — Trace the parser operation</li><li>{@link Parle\Parser::validate} — Validate input</li></ul></div>
 * 
 * Parser class.
 *
 * Rules can be defined on the fly. Once finalized, a Parle\Lexer instance is required to deliver the token stream.
 *
 * @see Lexer
 * @package Parle
 */
class Parser
{
    /* Constants */
    public const ACTION_ERROR = 0;
    public const ACTION_SHIFT = 1;
    public const ACTION_REDUCE = 2;
    public const ACTION_GOTO = 3;
    public const ACTION_ACCEPT = 4;
    public const ERROR_SYNTAX = 0;
    public const ERROR_NON_ASSOCIATIVE = 1;
    public const ERROR_UNKNOWN_TOKEN = 2;

    /* Properties */
    /**
     * @var int Current parser action that matches one of the action class constants, readonly.
     */
    #[Immutable]
    public $action = 0;

    /**
     * @var int Grammar rule id just processed in the reduce action. The value corresponds either to a token or to a production id. Readonly.
     */
    #[Immutable]
    public $reduceId = 0;

    /* Methods */
    /**
 * <div id="parle-parser.advance" class="refentry"> <div class="refnamediv">  <h1 class="refname">Parle\Parser::advance</h1>  <p class="verinfo">(PECL parle &gt;= 0.5.1)</p><p class="refpurpose"><span class="refname">Parle\Parser::advance</span> — <span class="dc-title">Process next parser rule</span></p> </div> <div class="refsect1 description" id="refsect1-parle-parser.advance-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Parle\Parser::advance</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">   Process next parser rule.  </p> </div> <div class="refsect1 parameters" id="refsect1-parle-parser.advance-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-parle-parser.advance-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。     </p> </div></div>
 * 
     * Process next parser rule.
     *
     * @link https://php.net/manual/zh/parle-parser.advance.php
     * @return void
     */
    public function advance(): void {}

